using System.Windows; using TextBox=System.Windows.Controls.TextBox; using ListBox=System.Windows.Controls.ListBox; using SelectionMode=System.Windows.Controls.SelectionMode; using StackPanel=System.Windows.Controls.StackPanel; using TextBlock=System.Windows.Controls.TextBlock; using Button=System.Windows.Controls.Button; namespace CloudServer; public sealed class GroupDialog:Window { readonly TextBox name=new(); readonly ListBox members=new(){SelectionMode=SelectionMode.Multiple}; readonly StateStore store; public string GroupName=>name.Text.Trim(); public List<string> UserIds=>members.SelectedItems.Cast<UserChoice>().Select(x=>x.Id).ToList(); public GroupDialog(StateStore s,CloudGroup? group=null){store=s;Title=group==null?"Gruppe hinzufügen":"Gruppe bearbeiten";Width=480;Height=560;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(new TextBlock{Text=Title,FontSize=24,FontWeight=FontWeights.Bold});p.Children.Add(new TextBlock{Text="Gruppenname",Margin=new Thickness(0,18,0,5)});name.Height=34;name.Text=group?.Name??"";p.Children.Add(name);p.Children.Add(new TextBlock{Text="Mitglieder",Margin=new Thickness(0,18,0,5)});members.Height=320;foreach(var u in s.State.Users){var x=new UserChoice(u.Id,u.DisplayName.Length>0?u.DisplayName+" ("+u.UserName+")":u.UserName);members.Items.Add(x);if(group!=null&&u.GroupIds.Contains(group.Id))members.SelectedItems.Add(x);}p.Children.Add(members);var ok=new Button{Content="Speichern",Height=42,Margin=new Thickness(0,22,0,0)};ok.Click+=(_,__)=>{if(string.IsNullOrWhiteSpace(GroupName)){System.Windows.MessageBox.Show("Bitte einen Gruppennamen eingeben.");return;}DialogResult=true;};p.Children.Add(ok);Content=p;} sealed record UserChoice(string Id,string Name){public override string ToString()=>Name;} }